init:
const centers = [[2.5, 2.5], [7, 3], [5, 7.5]];
const pts = range(60).map((i) => { const c = centers[i % 3]; return [clamp(randn(c[0], 0.9), 0.2, 9.8), clamp(randn(c[1], 0.9), 0.2, 9.8)]; });
return { pts, cents: [[1, 9], [2, 8.5], [3, 9]], iter: 0 };

components.onTick:
const lab = state.pts.map((p) => argmin(state.cents.map((c) => dist(p, c))));
const cents = state.cents.map((c, j) => { const m = state.pts.filter((p, i) => lab[i] === j); return m.length ? [mean(m.map((p) => p[0])), mean(m.map((p) => p[1]))] : c; });
const moved = sum(cents.map((c, j) => dist(c, state.cents[j])));
if (moved < 1e-6) return null;
return { cents, iter: state.iter + 1 };

components.onClick:
const lab = state.pts.map((p) => argmin(state.cents.map((c) => dist(p, c))));
const cents = state.cents.map((c, j) => { const m = state.pts.filter((p, i) => lab[i] === j); return m.length ? [mean(m.map((p) => p[0])), mean(m.map((p) => p[1]))] : c; });
return { cents, iter: state.iter + 1 };

components.draw:
const pal = ['blue', 'orange', 'green', 'purple', 'pink', 'teal'];
const lab = state.pts.map((p) => argmin(state.cents.map((c) => dist(p, c))));
return [
  points(state.pts, { colors: lab.map((j) => pal[j]), opacity: 0.8 }),
  points(state.cents, { id: 'c', draggable: true, colors: state.cents.map((c, j) => pal[j]), r: 10 })
];
